const body = $input.item.json.body || $input.item.json;
const supabaseUrl = $input.item.json._supabase_url;
const serviceKey  = $input.item.json._service_key;
const invoiceId   = body.invoice_id || null;
const orgId       = body.organization_id || null;
const action      = body._action || 'emit';

if (!supabaseUrl || !serviceKey) throw new Error('Variaveis SUPABASE_URL e SUPABASE_SERVICE_KEY nao configuradas');
if (!orgId)     throw new Error('organization_id obrigatorio');
if (!invoiceId) throw new Error('invoice_id obrigatorio');

const sbH = { 'apikey': serviceKey, 'Authorization': 'Bearer ' + serviceKey };

const invRes = await fetch(
  supabaseUrl + '/rest/v1/invoices?id=eq.' + invoiceId + '&select=*',
  { headers: sbH }
);
if (!invRes.ok) throw new Error('Erro ao buscar invoice: ' + invRes.status);
const invArr = await invRes.json();
const invoice = Array.isArray(invArr) ? invArr[0] : invArr;
if (!invoice || !invoice.id) throw new Error('Invoice nao encontrado: ' + invoiceId);

const allowed = ['processando', 'pendente', 'rejeitada', 'aguardando'];
if (!allowed.includes(invoice.status)) {
  throw new Error('Invoice com status ' + invoice.status + ' nao pode ser emitido');
}

const clientRes = await fetch(
  supabaseUrl + '/rest/v1/clients?id=eq.' + invoice.client_id + '&select=id,name,company,document,email,address_street,address_number,address_complement,address_neighborhood,address_city,address_state,address_zip,folder_id',
  { headers: sbH }
);
if (!clientRes.ok) throw new Error('Erro ao buscar cliente: ' + clientRes.status);
const clientArr = await clientRes.json();
const client = Array.isArray(clientArr) ? clientArr[0] : clientArr;
if (!client || !client.id) throw new Error('Cliente nao encontrado');

const configRes = await fetch(
  supabaseUrl + '/rest/v1/organization_integrations?organization_id=eq.' + (invoice.organization_id || orgId) + '&integration_type=eq.notaas&select=config',
  { headers: sbH }
);
if (!configRes.ok) throw new Error('Erro ao buscar config Notaas: ' + configRes.status);
const configArr = await configRes.json();
const config = Array.isArray(configArr) ? (configArr[0] && configArr[0].config ? configArr[0].config : {}) : {};
if (!config.api_key) throw new Error('API Key da Notaas nao configurada');

const codigoServico = (invoice.codigo_servico || config.codigo_servico_padrao || '').replace(/\D/g, '');
const descricaoServico = invoice.descricao_servico || config.descricao_servico_padrao || 'Prestacao de servicos';
const aliquotaIss = invoice.aliquota_iss != null ? invoice.aliquota_iss : (config.aliquota_iss_padrao || 5);
if (!codigoServico) throw new Error('Codigo de servico nao configurado');

const docDigits = (client.document || '').replace(/\D/g, '');
const tomador = {};
if (docDigits.length === 11) tomador.cpf = docDigits;
else tomador.cnpj = docDigits;
tomador.nome = client.company || client.name;
tomador.email = client.email || null;
tomador.endereco = {
  logradouro: client.address_street || '',
  numero: client.address_number || '',
  complemento: client.address_complement || '',
  bairro: client.address_neighborhood || '',
  cidade: client.address_city || '',
  uf: client.address_state || '',
  cep: client.address_zip || ''
};

const baseUrl = config.sandbox_mode === true
  ? 'https://sandbox.notaas.com.br'
  : 'https://platform.notaas.com.br';

return [{ json: {
  _supabase_url:  supabaseUrl,
  _service_key:   serviceKey,
  _base_url:      baseUrl,
  _api_key:       config.api_key,
  _folder_id:     client.folder_id || null,
  _client_name:   (client.company || client.name || '').replace(/[^a-zA-Z0-9 ]/g, '').trim(),
  invoice_id:     invoice.id,
  organization_id: invoice.organization_id,
  client_id:      invoice.client_id,
  payment_id:     invoice.payment_id,
  notaas_id:      invoice.notaas_id || null,
  action,
  notaas_payload: {
    tomador,
    servico: { codigo: codigoServico, descricao: descricaoServico },
    valores: { total: invoice.valor_servico, aliquotaIss },
    competencia: invoice.competencia
  }
}}];

// Recebe o status da nota consultada na Notaas e monta o PATCH para o Supabase
const notaasData = $input.item.json;
const prev       = $('Preparar Dados').item.json;
const emitData   = $('Chamar API Notaas').item.json;

// Status retornado pela Notaas: issued | queued | processing | error | cancelled
const notaasStatus = notaasData.status || (emitData.queued ? 'queued' : 'error');

const statusMap = {
  issued:     'emitida',
  queued:     'aguardando',
  processing: 'processando',
  error:      'rejeitada',
  cancelled:  'cancelada'
};
const internalStatus = statusMap[notaasStatus] || 'rejeitada';

// Dados da nota (prioriza Consultar Notas, fallback para Chamar API)
const notaasId  = notaasData.invoiceId  || emitData.invoiceId  || prev.notaas_id || null;
const numero    = notaasData.numeroNfe  || emitData.numeroNfe  || null;
const pdfUrl    = notaasData.pdfUrl     || emitData.pdfUrl     || null;
const xmlUrl    = notaasData.xmlUrl     || emitData.xmlUrl     || null;
const chNFSe    = notaasData.chNFSe    || emitData.chNFSe     || null;
const emittedAt = notaasData.emittedAt  || emitData.emittedAt  || (internalStatus === 'emitida' ? new Date().toISOString() : null);
const erroMsg   = internalStatus === 'rejeitada'
  ? (notaasData.message || notaasData.error || emitData.message || emitData.error || 'Erro na emissao pela Notaas')
  : null;

// Monta o patch
const patch = { status: internalStatus };
if (internalStatus === 'emitida') {
  patch.notaas_id       = notaasId;
  patch.notaas_protocol = chNFSe;
  patch.numero          = numero;
  patch.pdf_url         = pdfUrl;
  patch.xml_url         = xmlUrl;
  patch.emitida_em      = emittedAt;
  patch.erro_mensagem   = null;
} else if (internalStatus === 'aguardando' || internalStatus === 'processando') {
  patch.notaas_id     = notaasId;
  patch.erro_mensagem = null;
} else {
  patch.erro_mensagem = erroMsg;
}

return [{ json: {
  _supabase_url:   prev._supabase_url,
  _service_key:    prev._service_key,
  invoice_id:      prev.invoice_id,
  organization_id: prev.organization_id,
  client_id:       prev.client_id,
  payment_id:      prev.payment_id,
  notaas_status:   notaasStatus,
  internal_status: internalStatus,
  patch
}}];

// Lê o invoice atualizado retornado pelo Supabase (return=representation)
const input = $input.item.json;
const invoice = Array.isArray(input) ? input[0] : input;

const success = invoice.status === 'emitida';
const isError = invoice.status === 'rejeitada';

return [{ json: {
  success,
  invoice_id:      invoice.id,
  organization_id: invoice.organization_id,
  client_id:       invoice.client_id,
  payment_id:      invoice.payment_id,
  status:          invoice.status,
  notaas_id:       invoice.notaas_id    || null,
  numero:          invoice.numero       || null,
  pdf_url:         invoice.pdf_url      || null,
  emitida_em:      invoice.emitida_em   || null,
  erro_mensagem:   isError ? (invoice.erro_mensagem || 'Nota rejeitada') : null
}}];
